import java.util.*; public class Prim { public static int mst(int[][]g){int n=g.length,total=0;int[]d=new int[n];Arrays.fill(d,Integer.MAX_VALUE);boolean[]v=new boolean[n];d[0]=0;for(int k=0;k<n;k++){int u=-1;for(int i=0;i<n;i++)if(!v[i]&&(u<0||d[i]<d[u]))u=i;v[u]=true;total+=d[u]==Integer.MAX_VALUE?0:d[u];for(int i=0;i<n;i++)if(g[u][i]>0&&!v[i]&&g[u][i]<d[i])d[i]=g[u][i];}return total;} }